"use client";
import {useEffect,useRef,useState,type FormEvent} from "react";
import "./MatrixSetup.css";
export type MatrixRoom={roomId:string;kind:"room"|"space";name:string;topic:string;membership:string;encrypted:boolean;joinRule:string;children:string[];parents:string[];members:{userId:string;membership:string}[];powerLevels:Record<string,unknown>;permissions:{level:number|"creator";canConfigure:boolean;canSetJoinRule:boolean;canLink:boolean;canSetPermissions:boolean;canInvite:boolean;canKick:boolean;canBan:boolean;canEncrypt:boolean;canSend:boolean}};
export type MatrixReview={id:string;action:string;args:Record<string,unknown>;endpoint:string;account:string|null;effects:string[];expiresAt:number};
export type MatrixInstance={instanceId:string;label:string;endpoint:string;mode:string;enabled:boolean;installed:boolean|null;configured:boolean|null;running:boolean|null;management:string;serverName:string|null;account:{userId:string;deviceId:string|null;externalSession:boolean;endpoint:string}|null;selected:{roomId?:string;spaceId?:string}|null;evidence:string;reviewId:string|null;view:{apiAvailable:boolean;authentication:string;observedAt:string;error?:string;loginFlows:{type:string}[];rooms?:MatrixRoom[];invitations?:{roomId:string;name:string}[];invitationState?:string;roomsComplete?:boolean;failures?:{roomId:string;error:string}[]}|null;operations:{id:string;action:string;state:string;error?:string;completed:string[];result:Record<string,unknown>}[]};
export type MatrixSetupProps={instance:MatrixInstance;review:MatrixReview|null;busy:boolean;error?:string;notice?:string;onRefresh:()=>void;onReview:(action:string,args:Record<string,unknown>)=>void;onApply:(secret?:string)=>void;onCancel:()=>void;onResume:(id:string)=>void;onControl:(action:string)=>void};
export function MatrixSetup({instance:i,review,busy,error,notice,onRefresh,onReview,onApply,onCancel,onResume,onControl}:MatrixSetupProps){
 const [method,setMethod]=useState("access-token"),[username,setUsername]=useState(""),[privilege,setPrivilege]=useState(""),[secret,setSecret]=useState(""),[revoke,setRevoke]=useState(false),[encryptionAck,setEncryptionAck]=useState(false),[testAck,setTestAck]=useState(false);
 const reviewElement=useRef<HTMLElement>(null);
 useEffect(()=>{setSecret("");if(review)reviewElement.current?.focus();},[review?.id,i.instanceId]);
 const v=i.view,authenticated=v?.authentication==="authenticated",rooms=v?.rooms||[],space=rooms.find(r=>r.roomId===i.selected?.spaceId),room=rooms.find(r=>r.roomId===i.selected?.roomId),flows=v?.loginFlows||[];
 const submit=(fn:(data:FormData)=>void)=>(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();fn(new FormData(e.currentTarget));};
 const reviewAction=(action:string,args:Record<string,unknown>)=>{setSecret("");onReview(action,args);};
 const uncertain=i.operations.find(op=>["unknown","partial","applying"].includes(op.state));
 const [newKind,setNewKind]=useState("room"),[encryptNew,setEncryptNew]=useState(false),[newEncryptionAck,setNewEncryptionAck]=useState(false);
 return <section className="zn-matrix-setup" aria-label="Matrix setup">
  <header><h3>Matrix setup</h3><button disabled={busy||!i.enabled} onClick={onRefresh}>Check server and account</button></header>
  {uncertain&&<p role="alert">A retained {uncertain.action.replaceAll("-"," ")} action needs reconciliation. Check the current account and rooms, then review its acknowledgement below. It will not be replayed automatically.</p>}
  {error&&<p role="alert" className="zn-matrix-setup__error">{error}</p>}{notice&&<p role="status">{notice}</p>}
  {v?.observedAt&&<p>Last checked: {new Date(v.observedAt).toLocaleString()} · {i.evidence}</p>}
  <ol className="zn-matrix-setup__evidence">
   <li><strong>Server</strong><span>{!i.enabled?"Connection disabled":v?.apiAvailable?"API available":"API not verified"}</span></li>
   <li><strong>Account</strong><span>{authenticated?(i.evidence==="fresh"?i.account?.userId:"Account saved · recheck"):v?.authentication==="expired"?"Session expired":i.account?"Needs verification":"Sign in required"}</span></li>
   <li><strong>Rooms</strong><span>{authenticated?rooms.length+" joined; "+(i.evidence!=="fresh"?"cached":v?.roomsComplete?"checked":"incomplete"):"Not verified"}</span></li>
  </ol>
  {v?.error&&<p role="status">Some checks are incomplete: {v.error.replaceAll("_"," ")}.</p>}
  {i.evidence!=="fresh"&&<p>Saved evidence needs a fresh check. Room and account actions are verified again before applying.</p>}
  <details open={!i.configured&&i.mode==="install"}><summary>Server and installation</summary>
   <dl><dt>Connection address</dt><dd>{i.endpoint}</dd><dt>Server identity</dt><dd>{i.serverName||"Determined by the homeserver"}</dd><dt>Management</dt><dd>{i.management==="hub-managed"?"This Hub’s local instance":"External; no process control"}</dd><dt>Installed / configured / running</dt><dd>{[i.installed,i.configured,i.running].map(x=>x===null?"Unknown":x?"Yes":"No").join(" / ")}</dd></dl>
   {i.mode==="install"&&!i.configured&&<><p>Next: configure this retained installation. Identity, signing keys and data will be preserved.</p><button disabled={busy} onClick={()=>onControl("configure")}>Review server configuration</button></>}
   {i.mode==="install"&&i.configured&&!i.running&&<><p>Next: start the configured server, then create an account or sign in.</p><button disabled={busy} onClick={()=>onControl("start")}>Review startup</button></>}
   <p>Private local servers keep public registration disabled. Publishing a federated server, DNS and TLS are separate deployment work.</p>
  </details>
  {!i.enabled?<p>Reconnect this saved Hub connection to continue. Disabling it does not log out or revoke a Matrix session.</p>:<>
  {review?<section ref={reviewElement} tabIndex={-1} className="zn-matrix-setup__review" aria-label="Review Matrix action"><h4>Review {review.action.replaceAll("-"," ")}</h4><p>{review.endpoint}{review.account?" · "+review.account:""}</p><ul>{review.effects.map(e=><li key={e}>{e}</li>)}</ul><dl>{Object.entries(review.args).map(([k,val])=><div key={k}><dt>{k}</dt><dd>{String(val)}</dd></div>)}</dl>
   <form onSubmit={e=>{e.preventDefault();onApply(secret||undefined);setSecret("");}}>
    {["login","bootstrap"].includes(review.action)&&<label>{review.action==="bootstrap"||review.args.method==="m.login.password"?"Password":review.args.method==="m.login.token"?"One-use login token":"Existing access token"}<input type="password" autoComplete={review.action==="bootstrap"?"new-password":"off"} required value={secret} disabled={busy} onChange={e=>setSecret(e.target.value)} maxLength={8192}/><small>This value is submitted only now, never retained in the review or browser storage.</small></label>}
    <p>Review expires {new Date(review.expiresAt).toLocaleTimeString()}.</p><div className="zn-matrix-setup__actions"><button type="submit" disabled={busy}>{busy?"Applying…":"Apply reviewed action"}</button><button type="button" disabled={busy} onClick={onCancel}>Cancel</button></div>
   </form></section>:<>
   {i.reviewId&&<button disabled={busy} onClick={()=>onResume(i.reviewId!)}>Resume saved review</button>}
   <section><h4>Account</h4>{i.account&&<p>{i.account.userId} · device {i.account.deviceId||"not reported"}</p>}
    <details open={!authenticated}><summary>{authenticated?"Sign in with another account":"Sign in"}</summary>
     <form onSubmit={submit(()=>reviewAction("login",{method,...(method==="m.login.password"?{username}:{})}))}>
      <label>Authentication method<select value={method} disabled={busy} onChange={e=>setMethod(e.target.value)}>
       <option value="access-token">Use an existing access token</option>
       {flows.some(f=>f.type==="m.login.password")&&<option value="m.login.password">Password</option>}
       {flows.some(f=>f.type==="m.login.token")&&<option value="m.login.token">One-use login token</option>}
      </select></label>
      {method==="m.login.password"&&<label>Matrix username<input required maxLength={255} autoComplete="username" value={username} onChange={e=>setUsername(e.target.value)} disabled={busy}/></label>}
      <p>Available server methods: {flows.map(f=>f.type).join(", ")||"not checked"}. SSO, OAuth or interactive registration that is not supported here requires a compatible Matrix client; you can then supply a session explicitly.</p>
      <button disabled={busy||!v?.apiAvailable}>Review sign-in</button>
     </form>
    </details>
    {i.mode==="install"&&i.configured&&<details><summary>Create an account on this local server</summary><p>This administrative bootstrap uses only this Hub-owned instance. It is separate from ordinary login. Public registration remains disabled.</p><form onSubmit={submit(()=>reviewAction("bootstrap",{username,admin:privilege==="admin"}))}>
     <label>Local username<input required pattern="[a-z0-9._=-]{1,255}" maxLength={255} value={username} disabled={busy} onChange={e=>setUsername(e.target.value)}/></label>
     <label>Privileges<select required value={privilege} disabled={busy} onChange={e=>setPrivilege(e.target.value)}><option value="">Choose privileges</option><option value="ordinary">Ordinary account</option><option value="admin">Homeserver administrator</option></select></label><button disabled={busy||!v?.apiAvailable}>Review account creation</button>
    </form></details>}
    {i.account&&<details><summary>Log out / revoke this session</summary><p>Disabling the Hub connection leaves this session valid. This action revokes the selected token at the homeserver; other sessions are retained.</p>{i.account.externalSession&&<label className="zn-matrix-setup__check"><input type="checkbox" checked={revoke} onChange={e=>setRevoke(e.target.checked)}/>I understand this supplied session may also be used by another client.</label>}<button disabled={busy||(i.account.externalSession&&!revoke)} onClick={()=>reviewAction("logout",{revokeExternal:revoke})}>Review logout</button></details>}
   </section>
   {authenticated&&<section><h4>Spaces and rooms</h4><p>Names, membership and permissions come from this homeserver. Only a bounded view of joined rooms and invitations is retained.</p>
    {v?.roomsComplete===false&&<p role="status">The room list is incomplete. Refresh or use a specific room identifier; no missing room is assumed absent.</p>}
    {v?.failures?.map(f=><p key={f.roomId}>{f.roomId}: {f.error.replaceAll("_"," ")}</p>)}
    <label>Selected space<select value={i.selected?.spaceId||""} disabled={busy} onChange={e=>{if(e.target.value)reviewAction("select-space",{spaceId:e.target.value});}}><option value="">Choose a joined space</option>{rooms.filter(r=>r.kind==="space").map(r=><option key={r.roomId} value={r.roomId}>{r.name}</option>)}</select></label>
    <ul className="zn-matrix-setup__rooms">{rooms.filter(r=>r.kind==="room").map(r=><li key={r.roomId}><button aria-pressed={room?.roomId===r.roomId} disabled={busy} onClick={()=>reviewAction("select-room",{roomId:r.roomId,...(space?.children.includes(r.roomId)?{spaceId:space.roomId}:{})})}>{r.name}</button><span>{r.encrypted?"Encrypted":"Unencrypted"} · {r.joinRule}{space?.children.includes(r.roomId)?" · in selected space":""}</span></li>)}</ul>
    <details><summary>Create a space or room</summary><form onSubmit={submit(d=>reviewAction("create-"+newKind,{name:String(d.get("name")),topic:String(d.get("topic")),visibility:String(d.get("visibility")),joinRule:String(d.get("joinRule")),encryption:encryptNew,...(encryptNew?{acknowledgeEncryption:newEncryptionAck}:{})}))}>
     <label>Create<select value={newKind} disabled={busy} onChange={e=>setNewKind(e.target.value)}><option value="room">Room</option><option value="space">Space</option></select></label><label>Name<input name="name" required maxLength={200}/></label><label>Description<input name="topic" maxLength={1000}/></label><label>Directory visibility<select name="visibility"><option value="private">Private / unlisted</option><option value="public">Published in server directory</option></select></label><label>Joining<select name="joinRule"><option value="invite">Invitation required</option><option value="public">Public</option><option value="knock">Knock to request membership</option></select></label>
     <label className="zn-matrix-setup__check"><input type="checkbox" checked={encryptNew} onChange={e=>setEncryptNew(e.target.checked)}/>Enable encryption</label>
     {encryptNew&&<label className="zn-matrix-setup__check"><input required type="checkbox" checked={newEncryptionAck} onChange={e=>setNewEncryptionAck(e.target.checked)}/>Encryption cannot be disabled here. Device keys and encrypted messaging require an external Matrix client.</label>}
     <button disabled={busy}>Review creation</button>
    </form></details>
    <details><summary>Join by room ID, alias or invitation</summary><form onSubmit={submit(d=>reviewAction("join-room",{roomId:String(d.get("roomId"))}))}><label>Room ID or alias<input required name="roomId" placeholder="#room:example.org" maxLength={512}/></label><button disabled={busy}>Review join</button></form>
     {v?.invitations?.map(inv=><p key={inv.roomId}>{inv.name} <button disabled={busy} onClick={()=>reviewAction("join-room",{roomId:inv.roomId})}>Review invitation</button></p>)}{v?.invitationState!=="verified"&&<p>Invitations could not be checked. A restricted directory does not prevent joining by identifier.</p>}
    </details>
    {room&&<section className="zn-matrix-setup__room"><h4>{room.name}</h4><p>{room.roomId}</p><p>Membership: {room.membership}; power level: {room.permissions.level}. {room.encrypted?"Encrypted; device/key handling is not verified by this Hub.":"Unencrypted."}</p>
     <details><summary>Names, visibility and joining</summary><form key={room.roomId} onSubmit={submit(d=>reviewAction("configure-room",{roomId:room.roomId,name:String(d.get("name")),topic:String(d.get("topic")),...(d.get("joinRule")?{joinRule:String(d.get("joinRule"))}:{}),...(d.get("visibility")?{visibility:String(d.get("visibility"))}:{})}))}>
      <label>Name<input name="name" required maxLength={200} defaultValue={room.name}/></label><label>Description<input name="topic" maxLength={1000} defaultValue={room.topic}/></label><label>Join rule ({room.joinRule})<select name="joinRule"><option value="">Keep current</option><option value="invite">Invite only</option><option value="public">Public</option><option value="knock">Knock</option></select></label><label>Server directory<select name="visibility"><option value="">Keep current</option><option value="private">Unlisted</option><option value="public">Published</option></select></label><button disabled={busy||!room.permissions.canConfigure}>Review room changes</button>
     </form></details>
     {space&&<p><button disabled={busy||!space.permissions.canLink} onClick={()=>reviewAction(space.children.includes(room.roomId)?"unlink-room":"link-room",{roomId:room.roomId,spaceId:space.roomId})}>Review {space.children.includes(room.roomId)?"removing from":"adding to"} {space.name}</button></p>}
     <details><summary>Membership and permissions</summary><p>The cached membership list shows up to 200 states. The homeserver checks permissions for each requested change.</p><ul>{room.members.map(m=><li key={m.userId}>{m.userId} · {m.membership}</li>)}</ul><form onSubmit={submit(d=>reviewAction("membership",{roomId:room.roomId,userId:String(d.get("userId")),membership:String(d.get("membership"))}))}><label>Matrix user ID<input required name="userId" placeholder="@name:example.org"/></label><label>Action<select name="membership"><option value="invite">Invite</option><option value="kick">Remove</option><option value="ban">Ban</option><option value="unban">Unban</option></select></label><button disabled={busy}>Review membership</button></form>
      <form onSubmit={submit(d=>reviewAction("permissions",{roomId:room.roomId,userId:String(d.get("userId")),level:Number(d.get("level"))}))}><label>Matrix user ID<input required name="userId"/></label><label>Power level<input required type="number" min={Number.MIN_SAFE_INTEGER} max={Number.MAX_SAFE_INTEGER} name="level" defaultValue={0}/></label><button disabled={busy||!room.permissions.canSetPermissions}>Review permissions</button></form><details><summary>Current power-level state</summary><pre>{JSON.stringify(room.powerLevels,null,2)}</pre></details>
     </details>
     {!room.encrypted&&<details><summary>Enable encryption</summary><label className="zn-matrix-setup__check"><input type="checkbox" checked={encryptionAck} onChange={e=>setEncryptionAck(e.target.checked)}/>I understand encryption is permanent here and requires an external Matrix client for keys and encrypted messaging.</label><button disabled={busy||!encryptionAck||!room.permissions.canEncrypt} onClick={()=>reviewAction("enable-encryption",{roomId:room.roomId,acknowledgeEncryption:true})}>Review enabling encryption</button></details>}
     <details><summary>Optional message verification</summary><p>Send and read are separate checks. No test message is sent automatically.</p>{room.encrypted?<p>Open your E2EE-capable Matrix client, connect to {i.endpoint}, sign in as {i.account?.userId}, and open {room.roomId}. Device verification, key handling and encrypted send/read remain unverified by this Hub.</p>:<><label className="zn-matrix-setup__check"><input type="checkbox" checked={testAck} onChange={e=>setTestAck(e.target.checked)}/>Send “Zenith Hub connection verification.” to {room.name} and read that exact event.</label><button disabled={busy||!testAck||!room.permissions.canSend} onClick={()=>reviewAction("message-test",{roomId:room.roomId,acknowledgeSend:true})}>Review message test</button></>}</details>
    </section>}
   </section>}
  </>}
  </>}
  {i.operations.length>0&&<details open={!!uncertain}><summary>Retained action results</summary>{i.operations.map(op=><article key={op.id}><strong>{op.action.replaceAll("-"," ")} · {op.state}</strong>{op.error&&<p>{op.error.replaceAll("_"," ")}</p>}<p>{op.completed.join(" → ")||"No completed step recorded"}</p>{Object.keys(op.result).length>0&&<pre>{JSON.stringify(op.result,null,2)}</pre>}{["unknown","partial","applying"].includes(op.state)&&<><p>Check the current account and rooms before acknowledging this outcome. Nothing will be replayed automatically.</p><button disabled={busy} onClick={()=>reviewAction("acknowledge-outcome",{operationId:op.id,acknowledge:true})}>Review acknowledgement</button></>}</article>)}</details>}
 </section>;
}
